WITH cycles AS (SELECT pi1.id AS id_a, pi2.id AS id_b FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id AND pi2.canonical_image_id = pi1.id WHERE pi1.canonical_image_id IS NOT NULL AND pi2.canonical_image_id IS NOT NULL), root_per_cycle AS (SELECT LEAST(id_a, id_b) AS root_id, GREATEST(id_a, id_b) AS dep_id FROM cycles) UPDATE public.product_images pi SET canonical_image_id = NULL, last_modified_source = 'claude', updated_at = now() FROM root_per_cycle r WHERE pi.id = r.root_id; WITH RECURSIVE walk AS (SELECT id AS leaf_id, canonical_image_id AS next_id, 0 AS depth FROM public.product_images WHERE canonical_image_id IS NOT NULL UNION ALL SELECT w.leaf_id, pi.canonical_image_id, w.depth + 1 FROM walk w JOIN public.product_images pi ON pi.id = w.next_id WHERE pi.canonical_image_id IS NOT NULL AND w.depth < 5), roots AS (SELECT leaf_id, MAX(depth) FILTER (WHERE next_id IS NULL) AS max_d FROM walk GROUP BY leaf_id) SELECT NULL; UPDATE public.product_images SET canonical_image_id = NULL WHERE id IN (SELECT pi1.id FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id WHERE pi2.canonical_image_id IS NOT NULL AND pi1.canonical_image_id IS NOT NULL);;
